mapper.select:
SELECT 
FROM TBL_PAYABLE_DOCUMENT d
LEFT JOIN TBL_SUPPLIER s ON d.SUPPLIER_ID = s.SUPPLIER_ID
WHERE d.IS_DELETED = 0

    AND d.DOCUMENT_NO LIKE CONCAT('%', #{param.documentNo}, '%')


    AND d.SUPPLIER_ID = #{param.supplierId}


    AND s.SUPPLIER_NAME LIKE CONCAT('%', #{param.supplierName}, '%')


    AND d.DOCUMENT_STATUS = #{param.documentStatus}


    AND d.BUSINESS_TYPE = #{param.businessType}


    AND d.DUE_DATE >= #{param.dueDateStart}


    AND d.DUE_DATE <= #{param.dueDateEnd}


    AND d.PAYABLE_AMOUNT >= #{param.minAmount}


    AND d.PAYABLE_AMOUNT <= #{param.maxAmount}


    AND d.CURRENCY = #{param.currency}


    AND (d.DOCUMENT_NO LIKE CONCAT('%', #{param.keyword}, '%')
         OR s.SUPPLIER_NAME LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY d.CREATE_TIME DESC
